    public static function reference(string $component): ?array
    {
        if (! in_array($component, self::COMPONENTS, true)) {
            return null;
        }
        [$layer, $name] = explode('.', $component, 2);

        return [
            'main' => 'idea-to-paper-props-and-connections',
            'reference_index' => 'reference-'.$layer,
            'reference_'.$layer => 'reference-'.($layer === 'parts' ? 'parts-' : '').$name,
        ];
    }

    public static function examples(string $component): array
    {
        return array_filter(self::EXAMPLES, fn ($example) => in_array($component, $example['components'], true));
    }

    public static function url(array $tabs, string $fragment = 'tw-graph-documentation'): string
    {
        // Livewire updates are POSTed to /livewire/update; links must keep the page URL.
        return Livewire::originalUrl().'?'.http_build_query(['graph-tabs' => $tabs]).'#'.$fragment;
    }
}
